ORIENTATIONS = ["南","北","东南","南北","西南","东西"]
DECORATIONS = ["精装","精装","简装","豪装","毛坯"]
HOUSE_TYPES = [("一居室",0.18,1,55,10),("两居室",0.38,2,80,12),("三居室",0.32,3,110,18),("四居室",0.12,4,150,25)]
BCRYPT_HASH = "$2b$10$Y2c85Ceb/V4vs8.xQ1kn3u/PpR2BBIDo6ndgCyqhYso.XxnnfuYgC"

def wchoice(items):
    total = sum(w for _, w in items)
    r = random.random() * total; cum = 0
    for val, w in items:
        cum += w
        if r <= cum: return val
    return items[-1][0]

def gen_houses(n, nusers, fn):
    print(f"生成 {n:,} 房源(全国 30 城分布)...", flush=True)
    city_weight = [(c, c[2]) for c in CITIES]
    with open(fn,"w",encoding="utf-8",newline="") as f:
        w = csv.writer(f)
        for i in range(1, n+1):
            chosen_city = wchoice(city_weight)
            city, prov, _, districts = chosen_city
            dname = wchoice([(d[0],d[3]) for d in districts])
            dinfo = next(d for d in districts if d[0]==dname)
            ht = wchoice([(t[0],t[1]) for t in HOUSE_TYPES])
            ti = next(t for t in HOUSE_TYPES if t[0]==ht)
            area = max(20, round(random.gauss(ti[3], ti[4]), 2))
            price = max(800, round(random.gauss(dinfo[1], dinfo[2]), 2))
            title = f"{dname}{ht} 精装修 靠近地铁 拎包入住"
            lid = random.randint(1, nusers)
            t = (datetime.now()-timedelta(days=random.randint(0,730))).strftime("%Y-%m-%d %H:%M:%S")
            w.writerow([lid, title, f"{title}，配套齐全，交通便利，{city}{dname}优质房源",
                prov, city + "市", dname, f"{dname}路{random.randint(1,999)}号",
                area, ti[2], random.randint(1,2), random.randint(1,2),
                random.randint(1,30), random.randint(6,33), random.choice(ORIENTATIONS),
                random.choice(DECORATIONS), wchoice([("WHOLE",0.65),("SHARED",0.35)]),
                price, random.choice(["月付","季付","年付"]),
                "空调,洗衣机,冰箱,热水器,宽带,天然气",
                wchoice([("AVAILABLE",0.60),("RENTED",0.30),("OFFLINE",0.10)]),
                int(random.expovariate(1/500)), t, t, 0])
            if i % 100000 == 0: print(f"  {i:,}/{n:,}", flush=True)
    print("=== houses.csv 完成 ===", flush=True)

if __name__ == "__main__":
    nh = int(sys.argv[1]) if len(sys.argv)>1 else 400000
    nu = int(sys.argv[2]) if len(sys.argv)>2 else 800000
    gen_houses(nh, nu, "/tmp/houses.csv")
    print(f'CSV 大小: {os.path.getsize("/tmp/houses.csv")/1024/1024:.1f} MB', flush=True)